#pragma once
#include "state.hpp"
#include "metrics.hpp"
namespace cs {
struct Individual {int id=0,parent=-1;std::array<double,59> genome{};double fitness=0;bool fertile=false;};
class Evolution {
public:
 std::unique_ptr<Simulation>&sim;Config base;Json target=defaultTarget();
 std::mt19937_64 rng{0};std::vector<Individual>population;
 std::vector<Json>rows,history,validationResults;std::vector<std::string>rejected;
 int generation=0,slot=0,nextId=0,episodeSteps=7500,lastSample=-1,validationSeed=-1,stagnant=0,restarts=0;
 bool done=false;double bestFitness=-1,ancestorFitness=0,startTime=0,totalTime=0;
 std::array<double,59>ancestor{},bestGenome{},candidate{};
 bool continuousMode=false;int peakLiving=0,continuousSamples=0,lastEpisodePeak=0,lastMutationLoci=0,totalMutationLoci=0;double continuousScore=0,continuousHealthy=0,continuousSugar=0,continuousWaste=0,lastEpisodeDuration=0,lastEpisodeFitness=0;std::string lastTransition="尚未换代";
 Json baselineState,representativeState,baselineMetrics,validationRow,report;
 std::string phase="searching";std::filesystem::path output;
 explicit Evolution(std::unique_ptr<Simulation>&s,const Config&cfg,bool continuous=false):sim(s),base(cfg),continuousMode(continuous){rng.seed(uint64_t(cfg.random_seed));std::fill_n(ancestor.begin(),10,1.);if(!base.genome.empty())std::copy(base.genome.begin(),base.genome.end(),ancestor.begin());bestGenome=ancestor;if(continuousMode)startContinuousEpisode(ancestor);else{for(int i=0;i<8;i++)population.push_back(individual(i?mutate(ancestor):ancestor,-1));startEpisode();}}
 std::array<double,59>mutate(std::array<double,59>v,double probability=.2,double sigma=.12){std::uniform_real_distribution<double>u(0,1);std::normal_distribution<double>n(0,sigma);std::array<bool,59>mask;for(auto&b:mask)b=u(rng)<probability;for(int i=0;i<59;i++){double z=n(rng);v[i]=clip(v[i]+(mask[i]?z:0),i<10?.5:-1,i<10?1.8:1);}return v;}
 Individual individual(std::array<double,59>v,int parent){return {nextId++,parent,v,0,false};}
 void start(const std::array<double,59>&genome,int seed){Config cfg=base;cfg.genome.assign(genome.begin(),genome.end());cfg.random_seed=seed;cfg.mutation_probability=0;sim=std::make_unique<Simulation>(cfg);rows.clear();lastSample=-1;}
 void startContinuousEpisode(const std::array<double,59>&genome){phase="生长中";candidate=genome;Config cfg=base;cfg.genome.assign(genome.begin(),genome.end());cfg.random_seed=base.random_seed+generation;cfg.division_mutation_probability=base.division_mutation_probability;sim=std::make_unique<Simulation>(cfg);rows.clear();lastSample=-1;peakLiving=0;continuousSamples=0;continuousScore=continuousHealthy=continuousSugar=continuousWaste=0;}
 void sampleContinuous(){int second=int(sim->time+1e-8);if(second==lastSample)return;lastSample=second;auto m=tissueMetrics(*sim);auto s=sim->statistics();int living=int(s["cells"].num());peakLiving=std::max(peakLiving,living);double health=living?double(s["healthy"].num())/living:0;double size=std::log1p(double(living))/std::log1p(300.);double sugar=clip(m["sugar_delivery"].num())*clip(m["sugar_coverage"].num()),waste=clip(m["waste_delivery"].num())*clip(m["waste_coverage"].num());continuousScore+=.25*health+.2*size+.275*sugar+.275*waste;continuousHealthy+=health;continuousSugar+=sugar;continuousWaste+=waste;continuousSamples++;rows.push_back(m);if(rows.size()>240)rows.erase(rows.begin());}
 double continuousFitness()const{double duration=sim->time;double survival=1-std::exp(-duration/300.);double mean=continuousSamples?continuousScore/continuousSamples:0;double size=std::log1p(double(peakLiving))/std::log1p(300.);return .35*survival+.25*size+.4*mean;}
 void finishContinuousEpisode(bool allDead){
  double score=continuousFitness();lastEpisodeDuration=sim->time;lastEpisodePeak=peakLiving;lastEpisodeFitness=score;lastTransition=allDead?"全部细胞死亡":"达到换代时间上限";
  Json row=Json::object();row["generation"]=generation;row["fitness"]=score;row["duration"]=sim->time;row["peak_cells"]=peakLiving;row["transition"]=lastTransition;row["samples"]=continuousSamples;row["best_before"]=bestFitness;
  if(score>bestFitness){bestFitness=score;bestGenome=candidate;ancestorFitness=score;}
  auto parent=bestGenome;auto child=mutate(parent,base.evolution_mutation_probability,base.evolution_mutation_sigma);lastMutationLoci=0;
  for(size_t i=0;i<child.size();i++)if(child[i]!=parent[i])lastMutationLoci++;
  totalMutationLoci+=lastMutationLoci;row["next_mutated_loci"]=lastMutationLoci;row["next_parent_fitness"]=bestFitness;journal("continuous-generations",row);
  generation++;startContinuousEpisode(child);
 }
 void startEpisode(){phase="searching";start(slot==int(population.size())?ancestor:population[slot].genome,1000);}
 void journal(const std::string&name,const Json&row){if(output.empty())return;std::filesystem::create_directories(output);std::ofstream stream(output/(name+".jsonl"),std::ios::app|std::ios::binary);stream<<row.dump()<<'\n';}
 void sample(){int second=int(sim->time+1e-8);if(second==lastSample)return;lastSample=second;auto m=tissueMetrics(*sim);m["passes"]=samplePasses(m,target);rows.push_back(m);double cutoff=sim->time-target["stable_time"].num();while(rows.size()>1&&rows[1]["time"].num()<=cutoff)rows.erase(rows.begin());}
 bool accepted()const{if(rows.empty()||rows.back()["time"].num()-rows.front()["time"].num()<target["stable_time"].num()-1e-8)return false;int passed=0;for(auto&r:rows){if(r["connected_living"].num()<target["living"].num()||r["healthy_fraction"].num()<target["healthy_fraction"].num())return false;passed+=r["passes"].boolean();}return double(passed)/rows.size()>=target["window_pass_fraction"].num()&&wasteStable(rows,target);}
 void checkBalance()const{auto s=sim->statistics();for(auto name:{"sugar_balance_error","waste_balance_error","biomass_balance_error"})if(!std::isfinite(s[name].num())||std::abs(s[name].num())>1e-7)throw std::runtime_error("Material balance failed; target verification forbidden");}
 std::pair<double,bool>fitness()const{double mass=0;int living=0;for(auto&v:sim->c)if(v.alive){living++;mass+=v.mass*clip(1-v.damage/sim->cfg.death_damage_threshold);}bool fertile=living>=4&&mass>=5.6;if(!fertile||rows.empty())return {0,false};size_t width=std::max(size_t(1),rows.size()/4);double n=0,s=0,w=0,d=0;for(size_t i=rows.size()-width;i<rows.size();i++){auto&r=rows[i];n+=r["connected_living"].num()*r["healthy_fraction"].num();s+=std::min(1.,r["sugar_delivery"].num())*r["sugar_coverage"].num();w+=std::min(1.,r["waste_delivery"].num())*r["waste_coverage"].num();d+=r["waste_per_biomass"].num();}n/=width;s/=width;w/=width;d/=width;return {n*(.2+.4*s+.4*w+std::sqrt(s*w))*std::max(.1,1-d/target["max_waste_density"].num()),true};}
 std::string candidateKey()const{Json j=Json::array();for(double v:candidate)j.push(v);return j.dump();}
 void nextGeneration(){
  std::vector<int>fertile;double mean=0;for(int i=0;i<int(population.size());i++){mean+=population[i].fitness;if(population[i].fertile)fertile.push_back(i);}std::sort(fertile.begin(),fertile.end(),[&](int a,int b){return population[a].fitness>population[b].fitness;});Json row=Json::object();row["generation"]=generation;row["mean_fitness"]=mean/population.size();row["best_fitness"]=fertile.empty()?0:population[fertile[0]].fitness;row["ancestor_fitness"]=ancestorFitness;row["restarts"]=restarts;history.push_back(row);if(history.size()>128)history.erase(history.begin());journal("generations",row);
  std::vector<Individual>children;if(fertile.empty()){restarts++;for(int i=0;i<int(population.size());i++)children.push_back(individual(i?mutate(bestGenome):bestGenome,-1));}
  else{children.push_back(individual(population[fertile[0]].genome,population[fertile[0]].id));std::uniform_int_distribution<int>pick(0,int(fertile.size())-1);while(children.size()<population.size()){int winner=fertile[pick(rng)];for(int t=1;t<3;t++){int a=fertile[pick(rng)];if(population[a].fitness>population[winner].fitness)winner=a;}children.push_back(individual(mutate(population[winner].genome),population[winner].id));}}
  stagnant++;if(stagnant>=20){for(size_t i=std::max(size_t(1),children.size()/2);i<children.size();i++)children[i]=individual(mutate(bestGenome,.5,.24),children[i].parent);stagnant=0;}population=std::move(children);generation++;slot=0;
 }
 void finishEpisode(){checkBalance();auto[score,fertile]=fitness();Json row=Json::object();row["generation"]=generation;row["slot"]=slot;row["fitness"]=score;row["fertile"]=fertile;row["ancestor_control"]=slot==int(population.size());row["metrics"]=rows.empty()?tissueMetrics(*sim):rows.back();row["target_window_passed"]=accepted();journal("episodes",row);
  if(slot<int(population.size())){population[slot].fitness=score;population[slot].fertile=fertile;if(score>bestFitness){bestFitness=score;bestGenome=population[slot].genome;stagnant=0;}candidate=population[slot].genome;if(accepted()&&std::find(rejected.begin(),rejected.end(),candidateKey())==rejected.end()){validationSeed=0;validationResults.clear();startValidation();return;}}
  else ancestorFitness=score;slot++;if(slot>int(population.size()))nextGeneration();startEpisode();
 }
 void startValidation(){phase="baseline";start(candidate,101000+validationSeed);startTime=0;}
 void injury(){std::vector<double>load(sim->c.size());for(auto&e:sim->edges){double amount=std::abs(e.sugar)+std::abs(e.waste);load[e.a]+=amount;load[e.b]+=amount;}std::vector<int>live;for(int i=0;i<int(sim->c.size());i++)if(sim->c[i].alive)live.push_back(i);if(live.empty())return;int center=*std::max_element(live.begin(),live.end(),[&](int a,int b){return load[a]<load[b];});auto&v=sim->c[center];std::sort(live.begin(),live.end(),[&](int a,int b){return std::hypot(sim->c[a].x-v.x,sim->c[a].y-v.y)<std::hypot(sim->c[b].x-v.x,sim->c[b].y-v.y);});size_t count=std::max(size_t(1),size_t(std::ceil(live.size()*.1)));for(size_t i=0;i<count;i++)sim->kill(sim->c[live[i]]);validationRow["injured_cells"]=int(count);}
 void finishValidationSeed(){validationResults.push_back(validationRow);validationSeed++;if(validationSeed<int(target["validation_seeds"].num())){startValidation();return;}report=Json::object();Json counts=Json::object();bool passed=true;for(auto name:{"baseline","injury","environment"}){int count=0;for(auto&r:validationResults)count+=r[name].boolean();counts[name]=count;passed&=count>=int(target["validation_required"].num());}report["counts"]=counts;report["passed"]=passed;report["results"]=Json::array();for(auto&r:validationResults)report["results"].push(r);journal("validation",report);
  if(passed){done=true;phase="target_verified";sim=readState(representativeState);}else{rejected.push_back(candidateKey());validationSeed=-1;startEpisode();}}
 void finishPhase(){checkBalance();bool passed=false;if(phase=="baseline"){passed=accepted();validationRow=Json::object();validationRow["seed"]=101000+validationSeed;validationRow["baseline"]=passed;baselineMetrics=rows.empty()?tissueMetrics(*sim):rows.back();validationRow["baseline_metrics"]=baselineMetrics;}
  else{size_t width=std::max(size_t(1),rows.size()/4);passed=!rows.empty()&&wasteStable(rows,target);double sugar=0,waste=0;for(size_t i=rows.size()-std::min(width,rows.size());i<rows.size();i++){auto&r=rows[i];passed&=r["connected_living"].num()>=.5*baselineMetrics["connected_living"].num()&&r["healthy_fraction"].num()>=target["healthy_fraction"].num();sugar+=r["sugar_delivered_rate"].num();waste+=r["waste_delivered_rate"].num();}passed&=sugar/width>=target["recovery_fraction"].num()*baselineMetrics["sugar_delivered_rate"].num()&&waste/width>=target["recovery_fraction"].num()*baselineMetrics["waste_delivered_rate"].num();validationRow[phase]=passed;}
  Json log=Json::object();log["seed"]=validationSeed;log["phase"]=phase;log["passed"]=passed;log["rows"]=Json::array();for(auto&r:rows)log["rows"].push(r);journal("validation",log);
  if(phase=="baseline"){if(!passed){validationRow["injury"]=false;validationRow["environment"]=false;finishValidationSeed();return;}baselineState=stateJson(*sim);startTime=sim->time;injury();phase="injury";rows.clear();lastSample=-1;}
  else if(phase=="injury"){sim=readState(baselineState);sim->cfg.light_intensity*=.8;sim->cfg.substances["waste"].clearance_rate*=.8;phase="environment";rows.clear();lastSample=-1;}
  else{if(validationRow["baseline"].boolean()&&validationRow["injury"].boolean()&&passed)representativeState=baselineState;finishValidationSeed();}
 }
 void advance(int count=1){while(count--&&!done){sim->tick();totalTime+=sim->cfg.dt;if(continuousMode){sampleContinuous();int living=0;for(auto&v:sim->c)living+=v.alive;bool deathTurnover=living==0;bool timedTurnover=base.simulation_version=="V6"&&base.generation_time_limit>0&&sim->time>=base.generation_time_limit-1e-8;if(deathTurnover||timedTurnover)finishContinuousEpisode(deathTurnover);continue;}sample();if(validationSeed>=0){double limit=phase=="baseline"?episodeSteps*sim->cfg.dt:startTime+target["recovery_time"].num();if(sim->time>=limit-1e-8||(phase=="baseline"&&accepted()))finishPhase();}else if(sim->steps>=uint64_t(episodeSteps))finishEpisode();}}
 Json json()const{
  Json j=Json::object();j["format"]="native-v6-evolution-1";j["simulation"]=stateJson(*sim);j["base"]=base.json();j["target"]=target;j["generation"]=generation;j["slot"]=slot;j["nextId"]=nextId;j["episodeSteps"]=episodeSteps;j["lastSample"]=lastSample;j["validationSeed"]=validationSeed;j["stagnant"]=stagnant;j["restarts"]=restarts;j["done"]=done;j["bestFitness"]=bestFitness;j["ancestorFitness"]=ancestorFitness;j["startTime"]=startTime;j["totalTime"]=totalTime;j["phase"]=phase;j["continuousMode"]=continuousMode;j["peakLiving"]=peakLiving;j["continuousSamples"]=continuousSamples;j["continuousScore"]=continuousScore;j["continuousHealthy"]=continuousHealthy;j["continuousSugar"]=continuousSugar;j["continuousWaste"]=continuousWaste;j["lastEpisodePeak"]=lastEpisodePeak;j["lastEpisodeDuration"]=lastEpisodeDuration;j["lastEpisodeFitness"]=lastEpisodeFitness;j["lastTransition"]=lastTransition;j["lastMutationLoci"]=lastMutationLoci;j["totalMutationLoci"]=totalMutationLoci;std::ostringstream state;state<<rng;j["rng"]=state.str();
  for(auto[name,values]:{std::pair{"ancestor",&ancestor},{"bestGenome",&bestGenome},{"candidate",&candidate}}){j[name]=Json::array();for(double v:*values)j[name].push(v);}j["population"]=Json::array();for(auto&p:population){Json r=Json::object();r["id"]=p.id;r["parent"]=p.parent;r["fitness"]=p.fitness;r["fertile"]=p.fertile;r["genome"]=Json::array();for(double v:p.genome)r["genome"].push(v);j["population"].push(r);}for(auto[name,values]:{std::pair{"rows",&rows},{"history",&history},{"validationResults",&validationResults}}){j[name]=Json::array();for(auto&r:*values)j[name].push(r);}j["rejected"]=Json::array();for(auto&r:rejected)j["rejected"].push(r);j["baselineState"]=baselineState;j["representativeState"]=representativeState;j["baselineMetrics"]=baselineMetrics;j["validationRow"]=validationRow;j["report"]=report;return j;
 }
 void restore(const Json&j){if(j["format"].str()!="native-v6-evolution-1")throw std::runtime_error("Unsupported evolution checkpoint");base=Config::from(j["base"]);target=j["target"];sim=readState(j["simulation"]);
  generation=int(j["generation"].num());slot=int(j["slot"].num());nextId=int(j["nextId"].num());episodeSteps=int(j["episodeSteps"].num());lastSample=int(j["lastSample"].num());validationSeed=int(j["validationSeed"].num());stagnant=int(j["stagnant"].num());restarts=int(j["restarts"].num());done=j["done"].boolean();bestFitness=j["bestFitness"].num();ancestorFitness=j["ancestorFitness"].num();startTime=j["startTime"].num();totalTime=j["totalTime"].num();phase=j["phase"].str();if(j.has("continuousMode"))continuousMode=j["continuousMode"].boolean();if(j.has("peakLiving"))peakLiving=int(j["peakLiving"].num());if(j.has("continuousSamples"))continuousSamples=int(j["continuousSamples"].num());if(j.has("continuousScore"))continuousScore=j["continuousScore"].num();if(j.has("continuousHealthy"))continuousHealthy=j["continuousHealthy"].num();if(j.has("continuousSugar"))continuousSugar=j["continuousSugar"].num();if(j.has("continuousWaste"))continuousWaste=j["continuousWaste"].num();if(j.has("lastEpisodePeak"))lastEpisodePeak=int(j["lastEpisodePeak"].num());if(j.has("lastEpisodeDuration"))lastEpisodeDuration=j["lastEpisodeDuration"].num();if(j.has("lastEpisodeFitness"))lastEpisodeFitness=j["lastEpisodeFitness"].num();if(j.has("lastTransition"))lastTransition=j["lastTransition"].str();if(j.has("lastMutationLoci"))lastMutationLoci=int(j["lastMutationLoci"].num());if(j.has("totalMutationLoci"))totalMutationLoci=int(j["totalMutationLoci"].num());std::istringstream state(j["rng"].str());if(!(state>>rng))throw std::runtime_error("Invalid evolution RNG");
  for(auto[name,values]:{std::pair{"ancestor",&ancestor},{"bestGenome",&bestGenome},{"candidate",&candidate}}){if(j[name].a.size()!=59)throw std::runtime_error("Invalid genome");for(int i=0;i<59;i++)(*values)[i]=j[name].a[i].num();}population.clear();for(auto&r:j["population"].a){Individual p;p.id=int(r["id"].num());p.parent=int(r["parent"].num());p.fitness=r["fitness"].num();p.fertile=r["fertile"].boolean();if(r["genome"].a.size()!=59)throw std::runtime_error("Invalid population genome");for(int i=0;i<59;i++)p.genome[i]=r["genome"].a[i].num();population.push_back(p);}rows=j["rows"].a;history=j["history"].a;validationResults=j["validationResults"].a;rejected.clear();for(auto&r:j["rejected"].a)rejected.push_back(r.str());baselineState=j["baselineState"];representativeState=j["representativeState"];baselineMetrics=j["baselineMetrics"];validationRow=j["validationRow"];report=j["report"];
 }
};
}
